def mean(xs):
    return sum(xs) / len(xs)


def median(xs):
    ys = sorted(xs)
    n = len(ys)
    mid = n // 2
    if n % 2:
        return ys[mid]
    return (ys[mid - 1] + ys[mid]) / 2

